import java.util.Collection;

// Compatibility shim. The snippet on the page uses HashSet but its import list
// omits java.util.HashSet, so this small subclass lets the printed code compile
// and run unchanged. In your own programs, delete this file and add the line
// import java.util.HashSet; at the top of PlaylistApp.java instead.
public class HashSet<E> extends java.util.HashSet<E> {
    public HashSet() {
        super();
    }

    public HashSet(Collection<? extends E> source) {
        super(source);
    }
}
